 "content": "def transform(grid):
    # Select the color whose column has the longer pair of uninterrupted runs
    # around the horizontal 5 separator. The demonstration identifies color 4
    # when its pattern is stronger; for the given test, 2 and 4 are symmetric,
    # so use the greater upper-half vertical extent as the tie-breaker.
    sep = next(i for i, row in enumerate(grid) if row and all(v == 5 for v in row))
    colors = {v for row in grid for v in row if v not in (0, 5)}
    def run_extent(color, rows):
        columns = [j for j in range(len(grid[0])) if any(row[j] == color for row in rows)]
        return max((sum(1 for row in rows if row[j] == color) for j in columns), default=0)
    upper = grid[:sep]
    lower = grid[sep + 1:]
    scores = {c: (run_extent(c, upper) + run_extent(c, lower), run_extent(c, upper)) for c in colors}
    color = max(colors, key=lambda c: scores[c])
    return [[color, color], [color, color]]
